-- ============================================================
-- PART 1: Detail — each order and its projected_order flag
-- ============================================================
SELECT
    oh.order_no
    , oh.projected_order
    , CONVERT(DATE, oh.order_date)      AS order_date
    , oh.customer_id
    , a.name                            AS customer_name
FROM #portal_orders po
    INNER JOIN p21_view_oe_hdr oh
        ON oh.order_no = po.order_no
    LEFT JOIN p21_view_address a
        ON oh.customer_id = a.id
ORDER BY
    oh.projected_order DESC     -- Y first
    , oh.order_no


-- ============================================================
-- PART 2: Summary — count by projected_order value
-- ============================================================
SELECT
    oh.projected_order
    , COUNT(DISTINCT oh.order_no)   AS order_count
FROM #portal_orders po
    INNER JOIN p21_view_oe_hdr oh
        ON oh.order_no = po.order_no
GROUP BY
    oh.projected_order
ORDER BY
    oh.projected_order

DROP TABLE #portal_orders
